def prepare_existing_accounts(apps, schema_editor):
    user = apps.get_model("accounts", "User")
    user.objects.filter(is_staff=True).update(role="administrator")
    user.objects.filter(is_superuser=True).update(role="administrator", is_staff=True)
    profile = apps.get_model("accounts", "Profile")
    batch = []
    for user_id in user.objects.values_list("pk", flat=True).iterator(chunk_size=500):
        batch.append(profile(user_id=user_id))
        if len(batch) == 500:
            profile.objects.bulk_create(batch)
            batch = []
    if batch:
        profile.objects.bulk_create(batch)
    # Old sessions lack revocation tracking. Require a fresh login at the upgrade.
    apps.get_model("sessions", "Session").objects.all().delete()


